import itertools

def is_connected(edges, n, removed=set()):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        if u not in removed and v not in removed:
            adj[u].append(v)
            adj[v].append(u)
    # BFS from any non-removed vertex
    start = None
    for i in range(n):
        if i not in removed:
            start = i
            break
    if start is None:
        return False
    visited = [False]*n
    stack = [start]
    visited[start] = True
    count = 1
    while stack:
        u = stack.pop()
        for w in adj[u]:
            if not visited[w]:
                visited[w] = True
                count += 1
                stack.append(w)
    # Check all non-removed vertices are visited
    return count == n - len(removed)

def vertex_connectivity(edges, n):
    # Brute force check for small n
    for k in range(1, n):
        found = False
        for removed in itertools.combinations(range(n), k):
            if not is_connected(edges, n, set(removed)):
                found = True
                break
        if found:
            return k
    return n-1

