n = 15
edges = []
# hub edges
for i in range(1, n):
    edges.append((0, i))
# rim cycle
for i in range(1, n-1):
    edges.append((i, i+1))
edges.append((n-1, 1))

print("Number of edges:", len(edges))
print("Edges:", edges)
vc = vertex_connectivity(edges, n)
print("Vertex connectivity:", vc)
